<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/ReportingService.php';$svc=new ReportingService(Database::connection());$days=(int)($_GET['days']??30);$o=$svc->overview();$daily=$svc->daily($days);$types=$svc->transactionTypes($days);$segments=$svc->customerSegments();$top=$svc->topCustomers($days,10);if(($_GET['export']??'')==='daily'){ $svc->logExport((int)auth_user()['id'],'daily_transactions',['days'=>$days],'csv');header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="commserve-daily-report.csv"');echo $svc->exportDailyCSV($daily);exit;}
?><!doctype html><html lang="<?=e(current_locale())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(t('Executive Intelligence'))?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2><?=e(t('Executive Intelligence'))?></h2><p class="text-muted"><?=e(t('Management, customer and operational analytics.'))?></p></div><div><form class="d-inline"><select name="days" onchange="this.form.submit()" class="form-select d-inline-block w-auto"><option value="30" <?=$days===30?'selected':''?>>30 <?=e(t('days'))?></option><option value="90" <?=$days===90?'selected':''?>>90 <?=e(t('days'))?></option><option value="365" <?=$days===365?'selected':''?>>365 <?=e(t('days'))?></option></select></form> <a class="btn btn-outline-primary" href="?days=<?=$days?>&export=daily"><?=e(t('CSV Export'))?></a> <a class="btn btn-link" href="<?=url('admin/')?>"><?=e(t('Admin'))?></a></div></div><div class="row g-3 mb-4"><?php foreach([[t('Customers'),$o['customers']],[t('Accounts'),$o['accounts']],[t('Balance'),'$'.number_format($o['balance'],2)],[t('Completed volume'),'$'.number_format($o['completed_volume'],2)],[t('Transactions'),$o['transactions']],[t('Pending'),$o['pending_transactions']],[t('Risk alerts'),$o['risk_open']],[t('KYC queue'),$o['kyc_pending']]] as $c):?><div class="col-sm-6 col-xl-3"><div class="card border-0 shadow-sm"><div class="card-body"><div class="text-muted"><?=$c[0]?></div><div class="fs-3 fw-bold"><?=e((string)$c[1])?></div></div></div></div><?php endforeach;?></div><div class="row g-4"><div class="col-xl-8"><div class="card border-0 shadow-sm"><div class="card-body"><h5><?=e(t('Transaction Performance'))?></h5><canvas id="perf" height="105"></canvas></div></div></div><div class="col-xl-4"><div class="card border-0 shadow-sm"><div class="card-body"><h5><?=e(t('Customer Segments'))?></h5><canvas id="seg"></canvas></div></div></div></div><div class="row g-4 mt-1"><div class="col-xl-6"><div class="card border-0 shadow-sm"><div class="card-body"><h5><?=e(t('Transaction Channels / Types'))?></h5><canvas id="types"></canvas></div></div></div><div class="col-xl-6"><div class="card border-0 shadow-sm"><div class="card-body"><h5><?=e(t('Top Customers'))?> — <?=$days?> days</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th><?=e(t('Customer'))?></th><th><?=e(t('Transactions'))?></th><th><?=e(t('Volume'))?></th></tr></thead><tbody><?php foreach($top as $r):?><tr><td><?=e($r['customer'])?></td><td><?=$r['transactions']?></td><td>$<?=number_format((float)$r['volume'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><div class="card border-0 shadow-sm mt-4"><div class="card-body"><h5><?=e(t('Operational Performance'))?></h5><div class="table-responsive"><table class="table"><thead><tr><th><?=e(t('Date'))?></th><th><?=e(t('Transactions'))?></th><th><?=e(t('Completed'))?></th><th><?=e(t('Failed'))?></th><th><?=e(t('Volume'))?></th><th>Success rate</th></tr></thead><tbody><?php foreach(array_reverse($daily) as $r):$rate=(int)$r['transactions']?round(((int)$r['completed']/(int)$r['transactions'])*100,1):0;?><tr><td><?=$r['day']?></td><td><?=$r['transactions']?></td><td><?=$r['completed']?></td><td><?=$r['failed']?></td><td>$<?=number_format((float)$r['volume'],2)?></td><td><?=$rate?>%</td></tr><?php endforeach;?></tbody></table></div></div></div></div><script>const d=<?=json_encode($daily)?>,t=<?=json_encode($types)?>,s=<?=json_encode($segments)?>;new Chart(perf,{type:'line',data:{labels:d.map(x=>x.day),datasets:[{label:'Volume',data:d.map(x=>+x.volume),tension:.2},{label:'Completed',data:d.map(x=>+x.completed),yAxisID:'y1',tension:.2}]},options:{scales:{y:{beginAtZero:true},y1:{beginAtZero:true,position:'right'}}}});new Chart(seg,{type:'doughnut',data:{labels:s.map(x=>x.segment),datasets:[{data:s.map(x=>+x.customers)}]}});new Chart(types,{type:'bar',data:{labels:t.map(x=>x.type),datasets:[{label:'Completed volume',data:t.map(x=>+x.volume)}]},options:{indexAxis:'y'}});</script></body></html>